INSERT INTO `solutions` (`id`, `slug`, `title`, `problem_type`, `surface`, `material`, `severity`, `audience`, `diy_steps`, `warnings`, `when_to_call_pro`, `diy_cost_note`, `pro_time_note`, `search_keywords`, `related_category`, `video_url`, `reviewed_by`, `sources`, `status`, `created_at`, `updated_at`) VALUES ('mel-flomaster-na-oboyah', 'mel-flomaster-na-oboyah', 'Мел или фломастер на обоях', 'stain', 'wall', 'бумажные / флизелиновые / виниловые обои, окрашенные стены', 'set', 'b2c', '[{"order":1,"instruction":"Определите тип покрытия и маркера: бумажные и флизелиновые обои переносят только сухое удаление и слабый мыльный раствор, винил допускает спирт. Сначала проверьте выбранное средство на скрытом участке — за плинтусом или за мебелью.","tip":"Мел и вода — плохая пара: сначала уберите мел полностью сухим способом, иначе он превратится в серое пятно."},{"order":2,"instruction":"Мел смахните мягкой сухой щёткой или ластиком для обоев по направлению рисунка, затем пропылесосьте стену — не мочите её до полного удаления мела."},{"order":3,"instruction":"Фломастер: свежие чернила промокните сухой салфеткой, не размазывая. Водные маркеры ототрите чуть влажной микрофиброй с мыльной пеной pH 7. Перманентные маркеры выводятся изопропиловым спиртом точечно — только на виниловых и плотных обоях.","tip":"Спирт наносите на ватную палочку, а не на стену: чем меньше жидкости, тем меньше риск подтёка клея."},{"order":4,"instruction":"Промокните обработанное место чистой сухой салфеткой, дайте стене высохнуть и при необходимости повторите процедуру. Не трите круговыми движениями — так чернила только глубже въедутся в бумагу."}]', '["Не мочите обои и не трите щёткой: размокает клей, чернила расплывутся ореолом, а край обои может отклеиться от стены.","Не используйте ацетон, растворитель 646 и хлорку на бумажных и флизелиновых обоях — растворится верхний слой и краска рисунка.","Не применяйте спирт и агрессивные составы без теста на скрытом участке: цвет и фактура обоев могут измениться необратимо."]', 'Закрашена большая площадь стены, перманентный маркер въелся в флизелин или бумагу, обои уже отходят от стены, либо это не обои, а фактурная краска — специалист подберёт состав под конкретное покрытие и снимет след без подтёков клея.', '0 – 30 BYN (ластик для обоев, мыльная пена, изопропиловый спирт)', '30 – 60 минут на стену', '["мел на обоях","фломастер на стене","маркер на обоях","как отмыть мел","ручка на стене","пятно от фломастера","детские рисунки на обоях","отмыть маркер со стены"]', 'apartments', NULL, 'Редакция технологов ChistoLab', '["Технические карты и рекомендации производителей профессиональной химии (Kiehl, Prochem)","Методика оценки поверхностей и совместимости материалов — раздел «Методология» ChistoLab"]', 'published', 1794782558808, 1794782558808);
